// native_diar_register.cpp — registers every native of native_diar_decl.h with
// bronze (embed::registerNative) under __bro_native.diar. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_diar from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.diar.<Class>Proto for diar.js to chain.

#include "native_diar_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

bool ctor(const char* path, void* f, ev::HandleDestructor dtor, bronze::runtime::Finalize finalize,
          std::initializer_list<const char*> params, std::string* error) {
    ev::NativeSignature s = sig(path, params, ev::NativeKind::Constructor);
    s.className = path;
    s.destructor = dtor;
    s.finalize = finalize;
    return ev::registerNative(path, f, s, error);
}

// The prototype every instance of a class is born on, published where the
// wrapper reads it. Skipped when the roots are not there (bro-native-manifest
// registers without them; the manifest does not need the prototype).
void publishPrototype(const char* ns, const char* className, const char* protoName) {
    ev::GlobalValue root = ev::globalValue("__bro_native");
    if (!root.found || !ev::isObject(root.value)) return;
    ev::GlobalValue proto = ev::nativeClassPrototype(className);
    if (!proto.found) return;
    // Each value rooted before the next allocating call (bronze embed GC contract).
    ev::Persistent rootSlot(root.value);
    ev::Persistent protoSlot(proto.value);
    ev::Persistent nsSlot(ev::getProperty(rootSlot.get(), ns));
    if (!ev::isObject(nsSlot.get())) return;
    ev::setProperty(nsSlot.get(), protoName, protoSlot.get());
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_diar(std::string* error) {
    bool ok =
        ctor("__bro_native.diar.Sortformer", p(&bro_diar_Sortformer_ctor), &bro_diar_Sortformer_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.diar.SortformerSession", p(&bro_diar_SortformerSession_ctor), &bro_diar_SortformerSession_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.diar.ClusterDiarizer", p(&bro_diar_ClusterDiarizer_ctor), &bro_diar_ClusterDiarizer_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        fn("__bro_native.diar.Sortformer_createSession", p(&bro_diar_Sortformer_createSession), "__bro_native.diar.SortformerSession", {"__bro_native.diar.Sortformer"}, error) &&
        fn("__bro_native.diar.Sortformer_device_get", p(&bro_diar_Sortformer_device_get), "str", {"__bro_native.diar.Sortformer"}, error) &&
        fn("__bro_native.diar.Sortformer_busy_get", p(&bro_diar_Sortformer_busy_get), "bool", {"__bro_native.diar.Sortformer"}, error) &&
        fn("__bro_native.diar.SortformerSession_reset", p(&bro_diar_SortformerSession_reset), "void", {"__bro_native.diar.SortformerSession"}, error) &&
        fn("__bro_native.diar.SortformerSession_device_get", p(&bro_diar_SortformerSession_device_get), "str", {"__bro_native.diar.SortformerSession"}, error) &&
        fn("__bro_native.diar.SortformerSession_busy_get", p(&bro_diar_SortformerSession_busy_get), "bool", {"__bro_native.diar.SortformerSession"}, error) &&
        fn("__bro_native.diar.ClusterDiarizer_device_get", p(&bro_diar_ClusterDiarizer_device_get), "str", {"__bro_native.diar.ClusterDiarizer"}, error) &&
        fn("__bro_native.diar.ClusterDiarizer_busy_get", p(&bro_diar_ClusterDiarizer_busy_get), "bool", {"__bro_native.diar.ClusterDiarizer"}, error);
#if BRO_WITH_SOUNDML
    ok = ok &&
        fn("__bro_native.diar.init", p(&bro_diar_init), "void", {}, error);
#endif
    if (!ok) return false;
    publishPrototype("diar", "__bro_native.diar.Sortformer", "SortformerProto");
    publishPrototype("diar", "__bro_native.diar.SortformerSession", "SortformerSessionProto");
    publishPrototype("diar", "__bro_native.diar.ClusterDiarizer", "ClusterDiarizerProto");
    return true;
}

}  // namespace bro::bronze_host
